window.L5R_CHARACTER = {"slug":"aarav","name":"Aarav","clan":"The Sheelavaan of Bhavyatapura","family":"Fallen Noble (Gaijin)","school":"Ivory Kingdoms Sage Tradition","role":"Bushi","bucket":"Bushi","accent":"#fbf541","portrait":"src/portraits/aarav.png","concept":null,"summary":null,"tier_count":3,"xp_min":0,"xp_max":57,"twenty_questions":{"template":"pow","generated":true,"step1":{"clan":"The Sheelavaan of Bhavyatapura","ring":"air","skill":"courtesy","social_status":0},"step2":{"family":"Fallen Noble (Gaijin)","ring":"fire","skill1":"ranged","skill2":"command","wealth":0,"social_glory":28},"step3":{"school":"Ivory Kingdoms Sage Tradition","roles":"Bushi","ring1":"void","ring2":"earth","skill1":"melee","skill2":"unarmed","skill3":"meditation","skill4":"theology","skill5":"command","allowed_techniques":{"kata":true,"kiho":true,"inversion":false,"invocation":false,"ritual":true,"shuji":false,"maho":false,"ninjutsu":false,"mantra":false,"specificity":true},"techniques":["qFpqm3GpkCEAu6z2","5jLb6bvrYkwlkSc8","2iB4EK0I42kk83V3"],"school_ability":["xQRMG49wGf3rL3YS"],"equipment":["Cq1koK56k9dvLfMh","zcsgspz4VluSMeI0","tSwkJCF7OSXTVnvY","sjVz7tI11BkNAA7t","Rex7fGo6R1KuUhQJ","XsYJV8qKMImJ6PD0","7OWReYbIMfTvNrqv"],"social_honor":50},"step4":{"stand_out":"Gregarious and charming.","ring":"water"},"step5":{"social_giri":"Aarav's family was betrayed, his brothers executed; he fled east."},"step6":{"social_ninjo":"Regain his home; he seeks to reconquer his homeland."},"step7":{"clan_relations":"Aarav is famously handsome and kind, and a warrior of great prowess.","skill":"none","social_add_glory":5},"step8":{"bushido":"Aarav is unfamiliar with Bushido.","skill":"seafaring","social_add_honor":0,"tenet_paramount":"","tenet_less_significant":"","item":[]},"step9":{"success":"Survived the palace coup, and led his tutor's children to safety.","distinction":["qzkQyP8jGDoLiItw"]},"step10":{"difficulty":"He is unused to having to negotiate, to working with people who don't have to obey him.","adversity":["FCw1pfvIVYoe5yyk"]},"step11":{"calms":"Challenging himself, pushing himself.","passion":["B9fnpC0enRx8DeSO"]},"step12":{"worries":"Doubts about his fate to rule; perhaps the downfall of his family was karma?","anxiety":["TVReYB8XXXDEQUkr"]},"step13":{"most_learn":"The love of his life, Riya, is in another city. He is afraid that to visit her prematurely will bring danger to her, but their love has opened his eyes to the world in a way that he had previously been blind to.","skill":"none","advantage":["Vi9SQaa3y48ob8Hp"],"disadvantage":[]},"step14":{"first_sight":"His signet ring bears a tiger and his family's sigil.","special_features":["lh0BUCh3cKO0BUnn"]},"step15":{"stress":"He exercises strenuously, or practices archery."},"step16":{"relations":"His family's former vassals are scattered in exile or hiding in submission. Some noble houses have sworn fealty to the usurper, while others wait for a sign that restoration is possible.\n\nAs a foreign prince in Rokugan, he occupies an awkward position - too noble to ignore, but without the local connections that grant true influence. His royal blood means little here.\n\n","item":["uaCKNEXDlq1OI3wO"]},"step17":{"parents_pov":"Aarav has gathered a small group of mercenaries. They travel together, and he is trying to convince them to build their strength to help him return to power.","skill":"culture","bond":["ItUUhYTr7vst11ZH"]},"step18":{"heritage_name":"Raised in a royal suzerain's household, with servants and private tutors.","heritage_1":null,"heritage_2":null,"heritage_item":[],"heritage_add_honor":0,"heritage_add_glory":0,"heritage_add_status":0,"skill":"none"},"step19":{"firstname":"Aarav"},"step20":{"death":"He should die in an act of glorious heroism, defending his people."}},"notes":"","curriculum":[{"rank":1,"kind":"Skill Group","group":null,"label":"Scholar Skills","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Command","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Courtesy","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Fitness","prereq":false},{"rank":1,"kind":"Tech. Grp.","group":"kiho","label":"Rank 1 Kiho","prereq":false},{"rank":1,"kind":"Technique","group":"kata","label":"Landslide Strike","prereq":false},{"rank":1,"kind":"Technique","group":"shuji","label":"Bellow of Resolve","prereq":false},{"rank":2,"kind":"Skill Group","group":null,"label":"Martial Skills","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Composition","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Government","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Sentiment","prereq":false},{"rank":2,"kind":"Tech. Grp.","group":"kiho","label":"Rank 1-2 Kiho","prereq":false},{"rank":2,"kind":"Technique","group":"kata","label":"Rider's Haste","prereq":false},{"rank":2,"kind":"Technique","group":"kata","label":"Lord Hida’s Grip (Crab)","prereq":true},{"rank":3,"kind":"Skill Group","group":null,"label":"Martial Skills","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Courtesy","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Sentiment","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Theology","prereq":false},{"rank":3,"kind":"Tech. Grp.","group":"kata","label":"Rank 1-3 Kata","prereq":false},{"rank":3,"kind":"Technique","group":"kata","label":"Thunderous Hooves Style","prereq":true},{"rank":3,"kind":"Technique","group":"ritual","label":"Cleansing of Coral and Gold (Ivory Kingdoms Region)","prereq":true},{"rank":4,"kind":"Skill Group","group":null,"label":"Social Skills","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Fitness","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Martial Arts [Melee]","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Martial Arts [Unarmed]","prereq":false},{"rank":4,"kind":"Tech. Grp.","group":"kiho","label":"Rank 1-4 Kiho","prereq":false},{"rank":4,"kind":"Technique","group":"kata","label":"Striking as Void","prereq":true},{"rank":4,"kind":"Technique","group":"shuji","label":"Mentor's Guidance","prereq":true},{"rank":5,"kind":"Skill Group","group":null,"label":"Social Skills","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Martial Arts [Melee]","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Martial Arts [Unarmed]","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Meditation","prereq":false},{"rank":5,"kind":"Tech. Grp.","group":"kata","label":"Rank 1-5 Kata","prereq":false},{"rank":5,"kind":"Technique","group":"kiho","label":"Touch the Void Dragon","prereq":false},{"rank":5,"kind":"Technique","group":"shuji","label":"Buoyant Arrival","prereq":true}],"tiers":[{"xp":0,"label":null,"rank":1,"school":"Ivory Kingdoms Sage Tradition","foundry_id":"F5KInxHO1tSvc1KF","rings":{"air":2,"earth":2,"fire":2,"water":2,"void":2},"skills":{"artisan":{"aesthetics":0,"composition":0,"design":0,"smithing":0},"martial":{"fitness":0,"melee":1,"ranged":1,"unarmed":1,"meditation":1,"tactics":0},"scholar":{"culture":1,"government":0,"medicine":0,"sentiment":0,"theology":1},"social":{"command":2,"courtesy":1,"games":0,"performance":0},"trade":{"commerce":0,"labor":0,"seafaring":1,"skulduggery":0,"survival":0}},"social":{"honor":50,"glory":33,"status":0,"ninjo":"Regain his home; he seeks to reconquer his homeland.","giri":"Aarav's family was betrayed, his brothers executed; he fled east.","bushido_tenets":{"paramount":"","less_significant":""}},"derived":{"endurance":8,"composure":8,"focus":4,"vigilance":2,"void_points":2},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[],"techniques":[{"name":"Earth Needs No Eyes","kind":"kiho","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The monk who waits and listens sees much, even without eyes. Sending out waves of their own energy and letting the ki of the life around them flow back into their body through the ground, the monk feels the reverberations of everything moving nearby, from the thunderous breaths of a warrior in battle to the footsteps of the tiniest ants.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may activate this kihō. When you do so, you may make a </span><span class=\"fontstyle2\">TN 1 Meditation (earth) check </span><span class=\"fontstyle3\">to gain an awareness of your surroundings.</span></p><p><span class=\"fontstyle2\"><strong>Enhancement Effect:</strong> </span><span class=\"fontstyle3\">If you succeed, this kihō activates. While this kihō is active, you can use vibrations through the earth to “see” a number of range bands in all directions equal to your Earth Ring. While this kihō is active, increase your vigilance by your Earth Ring.</span></p><p><span class=\"fontstyle2\"><strong>Burst Effect:</strong> </span><span class=\"fontstyle3\">If you succeed with three or more bonus successes, you instantly become aware of all living creatures and objects touching the ground within a number of range bands equal to your Earth Ring plus your bonus successes.</span></p>","source":{"book":"core_rulebook","page":182},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kiho-l5r-sortilege.Item.qFpqm3GpkCEAu6z2","skill":"meditation","xp_cost":3},{"name":"Cleansing Spirit","kind":"kiho","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The monk centers their ki, then reaches out and touches another character, counterbalancing their turbulent energies with the stillness of the monk’s own soul. This restores the character’s spirit, driving out poison, disease, and even the grip of evil spirits, provided they have not yet taken root in the character’s soul.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, may make a </span><span class=\"fontstyle2\">TN 1 Theology (earth) check </span><span class=\"fontstyle3\">to bolster your spiritual resilience. When you perform this action, you may choose one other character at range 0–1 as the target for the burst effect.</span></p><p><span class=\"fontstyle2\"><strong>Enhancement Effect:</strong> </span><span class=\"fontstyle3\">If you succeed, this kihō activates. While this kihō is active, reduce the TN of all your checks to resist poison, disease, mahō, the Defiled terrain quality, and the effects of Otherworldly and Tainted beings by your Earth Ring.</span></p><p><span class=\"fontstyle2\"><strong>Burst Effect:</strong> </span><span class=\"fontstyle3\">If you have two or more bonus successes, remove one of the following conditions from your target: Afflicted, Bleeding, Dazed, Disoriented, Dying, Fatigued, or Intoxicated.</span></p>","source":{"book":"core_rulebook","page":182},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kiho-l5r-sortilege.Item.5jLb6bvrYkwlkSc8","skill":"theology","xp_cost":3},{"name":"Threshold Barrier","kind":"ritual","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The ritualist wards an entryway against beings of a certain sort, causing them to fail to observe the entryway or making them mentally repulsed by their efforts to enter it.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a downtime activity, you may make a </span><span class=\"fontstyle2\">TN 2 Theology check </span><span class=\"fontstyle3\">using (air), (earth), (fire), (water), or (void) targeting a threshold, gate, or other entryway at range 0–1.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, the threshold is barred against a particular type of entity, based on the ring you chose, for one hour, plus additional hours equal to your bonus successes. When an entity of this type attempts to enter, it must resist with a </span><span class=\"fontstyle2\">TN 3 Meditation (void) check </span><span class=\"fontstyle3\">or be repelled by the spiritual barrier. Whether it succeeds or fails, you immediately become aware of its attempted entry. The particular type of being is based on the ring you chose, as follows:</span></p><ul><li><p><span class=\"fontstyle2\">(air): </span><span class=\"fontstyle3\">Ethereal Otherworldly beings such as spirits and ghosts.</span></p></li><li><p><span class=\"fontstyle2\">(earth): </span><span class=\"fontstyle3\">Living Tainted beings.</span></p></li><li><p><span class=\"fontstyle2\">(fire): </span><span class=\"fontstyle3\">Undead beings with corporeal form.</span></p></li><li><p><span class=\"fontstyle2\">(water): </span><span class=\"fontstyle3\">Wild animals.</span></p></li><li><p><span class=\"fontstyle2\">(void): </span><span class=\"fontstyle3\">Humans.</span></p></li></ul><h4><span class=\"fontstyle5\">New Opportunities</span></h4><p><span class=\"fontstyle6\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">Instead of protecting a threshold, you may protect the entirety of a sealed area that extends a number of range bands around you no greater than your bonus successes.</span></p><p><span class=\"fontstyle6\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">If any beings of the type you are attempting to seal the threshold against have passed through the threshold within the last twenty-four hours, you become aware of their passage.</span></p>","source":{"book":"core_rulebook","page":213},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.2iB4EK0I42kk83V3","skill":"theology","xp_cost":3},{"name":"Gift of Inner Power","kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">You can infuse other characters with your inner energy. After you perform a check to activate one of your kihō, you can receive fatigue up to your school rank and choose another character at range 0–1. If you do, that character gains the enhancement effect of your kihō in your stead ­you may still resolve the burst effect, if able). This effect persists a number of rounds equal to the amount of fatigue you received this way plus your ranks in Meditation. Only one character can benefit from your kihō at a time.</span></p>","source":{"book":"path_of_waves","page":58},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.xQRMG49wGf3rL3YS","xp_cost":0}],"peculiarities":[{"name":"Blessed Lineage","kind":"distinction","ring":"void","types":"Interpersonal, Spiritual","description":"<p><span class=\"fontstyle0\"><em>“Perhaps you’d like to match your words with your steel,” the woman growled, her hands resting upon the hilts of her swords. “You will learn a hard lesson: nobody insults Mirumoto Ohatsu with impunity.”</em></span></p><p><span class=\"fontstyle0\"><em>The man she faced smiled in return.</em></span></p><p><span class=\"fontstyle0\"><em>“I certainly did not intend to offend you in any way, Ohatsu-san. Please allow me to introduce myself. I am Miya Matsuo. Perhaps you have heard of my cousin, the Imperial Herald?”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Blessed Lineage distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- Characters with status of 50 or higher understand that they might suffer a loss of prestige if they harm you, and thus do not choose to kill you as their first option, even if you are a political obstacle they would otherwise eliminate without hesitation.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check for which your esteemed lineage is a benefit (such as a Command (void) check to challenge someone’s perception of a situation or a Government (void) check to know the likelihood of a political eventuality), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":103},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.tRfoACKusbLsicmy","xp_cost":3},{"name":"Gaijin Name, Culture, or Appearance","kind":"adversity","ring":"fire","types":"Interpersonal (Culture) or Physical (Appearance), Interpersonal (Name), Mental","description":"<p><em>The Crane courtier bowed deeply, a thin, insincere smile upon his face. “I bring a thousand wishes for a glorious future from the Crane to the great Shinjo Aru…Arutan…”</em></p><p><em>“Altansarnai,” the Unicorn Champion corrected him. The courtier bowed further. “I apologize, Shinjo\u0002sama. A…lovely name, but one that falls oddly upon my tongue.”</em></p><p><em>“It is from the Ujik tongue. It means ‘golden rose.’” Altansarnai gestured for the courtier to join her where she was seated. We are still foreign to them, she thought, and they will never let us forget it.</em></p><p></p><p>The following apply to a character with the Gaijin Name, Culture, or Appearance adversity:</p><ul><li><p>- People of higher and equal status tend to assume that you are uneducated at best and a barbarian at worst, while people of lower status respond to you with fear.</p></li><li><p>- When you make a check to inspire others who do not share your culture or background (such as a Command (fire) check to rally troops or a Commerce (fire) check to create a product that people desire), you must choose and reroll two dice containing (su) or (ex) . After resolving the check, if you failed, you gain 1 Void point.</p></li></ul>","source":{"book":"core_rulebook","page":121},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.FCw1pfvIVYoe5yyk","xp_cost":3},{"name":"Glorious Deeds","kind":"passion","ring":"fire","types":"Martial, Social","description":"<p><span class=\"fontstyle0\"><em>“Even should a samurai evade death on the battlefield and survive to see their great-grandchildren come of age, one day they will pass. Such is the way of mortals. But the stories that people tell of that samurai—those may live forever.” The Ikoma historian gave his sibling a shrewd look.</em></span></p><p><span class=\"fontstyle0\"><em>“But you did not come to listen to the lectures I have for students, I suspect. You want to be the subject of my next lecture. Tell me of your accomplishments, and I will make sure they are recorded in the family histories.”</em></span></p><p><span class=\"fontstyle0\"><em>With that prompting, the eager bushi launched into a story about their efforts in the recent conflict, and they were not silent until late into the night.</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Glorious Deeds passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You find risking your life to be a simple matter, as long as there is a witness to remember your bravery. No threat or challenge deters you if you might be remembered for it, making even the most daunting tasks easy ones for which to prepare.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to improve your reputation or gain fame as a great samurai (such as a Performance (fire) check to impress a court with your new melody, or a Tactics (fire) check to execute a daring raid on the enemy), you remove 3 strife.</span></p></li></ul>","source":{"book":"fields_of_victory","page":83},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.B9fnpC0enRx8DeSO","xp_cost":3},{"name":"Fear of Mediocrity","kind":"anxiety","ring":"fire","types":"Interpersonal, Mental","description":"<p><em>“I have climbed the highest peaks in my quest: the Wrath of the Kami, Tenkenniyoru Yama, the Iron Mountain, the Northern Wall Mountains… Nothing!</em></p><p><em>Each tincture from a flower. Each tea from an herb. Each poultice from bark. Nothing. The answer must be out there.”</em></p><p><em>- letters from Agasha AriNaga regarding an elixir of immortality</em></p><p><em>“Falling up a mountain like AriNaga, to be immortalized as a fool.”</em></p><p><em>- old Agasha saying</em></p><p><strong>Effects:</strong> The following apply to a character with the Fear of Mediocrity anxiety:</p><ul><li><p>-  Your fear of amounting to nothing causes you to seize up when faced with the need to innovate on the fly.</p></li><li><p>-  After performing a check to adapt to an unexpected situation (such as a Survival (fire) check to find shelter when your tent is destroyed or a Culture (fire) check to unexpectedly interact in an appropriate manner with someone of a higher status), you receive 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"writ_of_the_wild","page":106},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.TVReYB8XXXDEQUkr","xp_cost":3},{"name":"Benten’s Blessing","kind":"distinction","ring":"air","types":"Interpersonal, Spiritual","description":"<p><span class=\"fontstyle0\"><em>Daidoji Shingen sauntered down the gangplank from the dock to his waiting vessel, a broad smile spreading across his face. His crew gathered around their returning captain.</em></span></p><p><span class=\"fontstyle0\"><em>“We have safe harbor here, and a fine market in which to sell our cargo. Start offloading.” The crew cheered, and set to work. Shingen’s first mate, Hiramichi Anjiro, remained behind, scratching his head idly.</em></span></p><p><span class=\"fontstyle0\"><em>“I don’t know how you managed that, Captain.” Shingen winked. “Let’s just say that the lady of the palace was kindly disposed toward a wayward sea captain.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Benten’s Blessing distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- After interacting with a character for one or more scenes, you know with certainty whether they are open to your romantic aspirations or if they are categorically uninterested.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check for which the favor of the Fortune Benten is a benefit (such as an Aesthetics (air) check to say something insightful about a piece of art or a Courtesy (air) check to convince someone of your positive qualities), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":102},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.Vi9SQaa3y48ob8Hp","xp_cost":3}],"titles":[],"bonds":[{"name":"Wanderers Fellowship","description":"<p><span class=\"fontstyle0\">With no lord, rōnin have nobody to rely upon and none to protect save themself, making their way through the world like waves rolling across the shore. But even the most independent-minded humans desire a degree of companionship, and there is a certain stability to be found in numbers. As a result, many rōnin form warrior bands, groups that work, fight, suffer, and laugh together. These bonds can become as tight as the tremendously strong bonds of family in Rokugan, or even stronger. In desperate circumstances, this bond can get a rōnin on their feet and back into the fight, helping them to fight on through the pain or face overwhelming odds to save their comrades in arms.</span></p><ul><li><p><span class=\"fontstyle0\">- Other members of your fellowship watch out for your safety (if not always your dignity, especially when it comes to telling embarrassing stories). They help you with modest favors (offering you a cut in on a job they have taken on, giving you an introduction to someone hiring rōnin, buying your sake when your purse is empty and theirs is less empty), and generally expect you to reciprocate such favors.</span></p></li><li><p><span class=\"fontstyle0\">- Those with whom your fellowship has worked before are generally inclined to regard you in the same way they do your fellows—if they are rowdy or well-behaved, they will assume the same of you. Your actions also reflect upon members of your fellowship, and if you step out of line such that it endangers the group’s reputation, they intervene to set you on the right path—or to remove you from the group, if you will not repent.</span></p></li><li><p><span class=\"fontstyle0\">- If your bond rank is 3 or higher, your fellowship’s bonds of loyalty are extremely deep, and other members will accept dangerous jobs with you without question, join your side in battles that do not pay, and perhaps even buy your sake without reminding you about it three times in the next week.</span></p></li></ul><p></p><p><span class=\"fontstyle3\"><strong>Bond Ability:</strong> Sworn to Duty and to Death</span></p>","source":{"book":"path_of_waves","page":191},"uuid":"Compendium.l5r5e-compendia-sortilege.bonds-l5r-sortilege.Item.ItUUhYTr7vst11ZH","xp_cost":3}],"gear":[{"name":"Talwar","quantity":1,"description":"<p><span class=\"fontstyle0\">The Ivory Kingdoms sidearm is the </span><span class=\"fontstyle2\">talwar</span><span class=\"fontstyle0\">, or “single-edged sword.” A curved saber with one sharp edge and a cross-guarded hilt with a knuckle-bow, it is designed to be wielded in a specialized one-handed grip. The sword’s hilt is bulb shaped, requiring that the sword be held differently than those forged by Rokugani. This and the blade’s unusual balance means that talwar fighting requires special training; attempting</span> <span class=\"fontstyle0\">to use the sword as one might a Rokugani blade can break the talwar or injure one’s wrist. However, when a talwar is wielded correctly, the wider cutting tip at the end of its blade affords it more cutting power, making this sidearm an especially deadly weapon.</span></p>","source":{"book":"path_of_waves","page":113},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.tSwkJCF7OSXTVnvY","damage":4,"deadliness":6,"range":"1","grip_2":"N/A","skill":"melee","category":"Swords","rarity":"8","zeni":"35 koku","properties":[{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Daikyū","quantity":1,"description":"<p><span class=\"fontstyle0\">Daikyū are large composite bows designed to be fired from horseback. Conventionally around six feet long, these elegant weapons are constructed by gluing thin layers of wood, horn, leather, and sinew together. Daikyū differ from other bows in that they have an asymmetric shape. Their grip is about two-thirds of the way from the top, making the top curve longer than the bottom. This allows the bows to be fired easily from horseback in either direction. Each daikyū is made for a custom fit for a specific user.</span></p>","source":{"book":"core_rulebook","page":236},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.sjVz7tI11BkNAA7t","damage":6,"deadliness":4,"range":"3-5","grip_1":"N/A","skill":"ranged","category":"Bows","rarity":"6","zeni":"6 koku","properties":[{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Gunbai","quantity":1,"description":"<p><span class=\"fontstyle0\">The gunbai, a leader or commander’s war fan, is a staple of samurai officers for communicating orders to their troops at a distance. Each gunbai is unique, as are the gestures the officers use to communicate orders to their troops. With a flick of the wrist, an officer may order their troops to fall back or to charge into the fray. Often gilded with metal, a gunbai is used to convey urgent tactical shifts and defensive moves.</span></p><p><span class=\"fontstyle0\">A gunbai can be wielded as a one-handed Martial Arts [Melee] weapon with the following profile: Range 1, Damage 2, Deadliness 2.</span></p><p><span class=\"fontstyle0\">During a skirmish, a character with a gunbai readied can perform shūji targeting characters who can see them at range 0–6 (as opposed to the usual auditory range restriction of range 0–4).</span></p><p><span class=\"fontstyle0\">During a mass battle, for each of an army’s leaders equipped with a gunbai, the army increases its discipline by 2.</span></p>","source":{"book":"fields_of_victory","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.7OWReYbIMfTvNrqv","damage":2,"deadliness":2,"range":"1","grip_2":"N/A","skill":"melee","category":"Hand Weapons","rarity":"4","zeni":"3 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Sanctified Robes","quantity":1,"description":"<p><span class=\"fontstyle0\">The vestments of shugenja, shrine keepers, and other religious figures are blessed by kami and thus grant mystical protection. Traditionally, such robes consist of a white garment called </span><span class=\"fontstyle2\">jōe </span><span class=\"fontstyle0\">(literally, “pure cloth”) and a peaked hat, but they can be simpler, such as a white haori top and red hakama bottoms, or even an elaborate kimono.</span></p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.Cq1koK56k9dvLfMh","armor":{"physical":1,"supernatural":3},"rarity":"7","zeni":"4 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p><span class=\"fontstyle0\">Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak</span>.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Map (Ivory Kingdoms)","quantity":1,"custom":true,"description":"<p><span class=\"fontstyle0\">Showing the route from the Ivory Kingdoms to the Sand Road</span>.</p>","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Signet Ring (Royal Family)","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Uma-Jirushi","quantity":1,"description":"<p>Resembling a soldier’s sashimono banner, the massive, heraldic uma-jirushi banner sets a daimyō or general apart as they ride into battle. While some uma-jirushi may simply be larger, more ornate sashimono, some daimyō contract artisans to create elaborate, three-dimensional shapes or even entreat shugenja to add elemental flourishes (such as a perpetual, slow-burning flame or a constant gust of wind) to make their banner stand out.</p><p data-start=\"440\" data-end=\"748\" data-is-last-node=\"\" data-is-only-node=\"\">When making a Command check, a leader in a mass battle who displays a personal uma-jirushi adds one kept  set to . Should the bearer of an uma-jirushi be killed via the Cut Off the Head or Challenge action, their army receives 4 additional panic. (Cost: 3 koku. Rarity: 7. Qualities: Resplendent, Wargear.)</p>","source":{"book":"fields_of_victory","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.uaCKNEXDlq1OI3wO","rarity":"7","zeni":"3 koku","properties":[{"id":"L5RCorePro000010","name":"Resplendent"},{"id":"L5RCorePro000011","name":"Wargear"}]}]},{"xp":36,"label":"Astradhari","rank":1,"school":"Ivory Kingdoms Sage Tradition","foundry_id":"Rd0ybxfqy3eSxSAQ","rings":{"air":2,"earth":2,"fire":2,"water":2,"void":2},"skills":{"artisan":{"aesthetics":0,"composition":0,"design":0,"smithing":0},"martial":{"fitness":0,"melee":1,"ranged":4,"unarmed":1,"meditation":1,"tactics":0},"scholar":{"culture":1,"government":0,"medicine":0,"sentiment":0,"theology":1},"social":{"command":3,"courtesy":1,"games":0,"performance":0},"trade":{"commerce":0,"labor":0,"seafaring":1,"skulduggery":0,"survival":0}},"social":{"honor":50,"glory":33,"status":0,"ninjo":"Regain his home; he seeks to reconquer his homeland.","giri":"Aarav's family was betrayed, his brothers executed; he fled east.","bushido_tenets":{"paramount":"","less_significant":""}},"derived":{"endurance":8,"composure":8,"focus":4,"vigilance":2,"void_points":2},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[],"techniques":[{"name":"Earth Needs No Eyes","kind":"kiho","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The monk who waits and listens sees much, even without eyes. Sending out waves of their own energy and letting the ki of the life around them flow back into their body through the ground, the monk feels the reverberations of everything moving nearby, from the thunderous breaths of a warrior in battle to the footsteps of the tiniest ants.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may activate this kihō. When you do so, you may make a </span><span class=\"fontstyle2\">TN 1 Meditation (earth) check </span><span class=\"fontstyle3\">to gain an awareness of your surroundings.</span></p><p><span class=\"fontstyle2\"><strong>Enhancement Effect:</strong> </span><span class=\"fontstyle3\">If you succeed, this kihō activates. While this kihō is active, you can use vibrations through the earth to “see” a number of range bands in all directions equal to your Earth Ring. While this kihō is active, increase your vigilance by your Earth Ring.</span></p><p><span class=\"fontstyle2\"><strong>Burst Effect:</strong> </span><span class=\"fontstyle3\">If you succeed with three or more bonus successes, you instantly become aware of all living creatures and objects touching the ground within a number of range bands equal to your Earth Ring plus your bonus successes.</span></p>","source":{"book":"core_rulebook","page":182},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kiho-l5r-sortilege.Item.qFpqm3GpkCEAu6z2","skill":"meditation","xp_cost":3},{"name":"Cleansing Spirit","kind":"kiho","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The monk centers their ki, then reaches out and touches another character, counterbalancing their turbulent energies with the stillness of the monk’s own soul. This restores the character’s spirit, driving out poison, disease, and even the grip of evil spirits, provided they have not yet taken root in the character’s soul.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, may make a </span><span class=\"fontstyle2\">TN 1 Theology (earth) check </span><span class=\"fontstyle3\">to bolster your spiritual resilience. When you perform this action, you may choose one other character at range 0–1 as the target for the burst effect.</span></p><p><span class=\"fontstyle2\"><strong>Enhancement Effect:</strong> </span><span class=\"fontstyle3\">If you succeed, this kihō activates. While this kihō is active, reduce the TN of all your checks to resist poison, disease, mahō, the Defiled terrain quality, and the effects of Otherworldly and Tainted beings by your Earth Ring.</span></p><p><span class=\"fontstyle2\"><strong>Burst Effect:</strong> </span><span class=\"fontstyle3\">If you have two or more bonus successes, remove one of the following conditions from your target: Afflicted, Bleeding, Dazed, Disoriented, Dying, Fatigued, or Intoxicated.</span></p>","source":{"book":"core_rulebook","page":182},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kiho-l5r-sortilege.Item.5jLb6bvrYkwlkSc8","skill":"theology","xp_cost":3},{"name":"Threshold Barrier","kind":"ritual","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The ritualist wards an entryway against beings of a certain sort, causing them to fail to observe the entryway or making them mentally repulsed by their efforts to enter it.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a downtime activity, you may make a </span><span class=\"fontstyle2\">TN 2 Theology check </span><span class=\"fontstyle3\">using (air), (earth), (fire), (water), or (void) targeting a threshold, gate, or other entryway at range 0–1.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, the threshold is barred against a particular type of entity, based on the ring you chose, for one hour, plus additional hours equal to your bonus successes. When an entity of this type attempts to enter, it must resist with a </span><span class=\"fontstyle2\">TN 3 Meditation (void) check </span><span class=\"fontstyle3\">or be repelled by the spiritual barrier. Whether it succeeds or fails, you immediately become aware of its attempted entry. The particular type of being is based on the ring you chose, as follows:</span></p><ul><li><p><span class=\"fontstyle2\">(air): </span><span class=\"fontstyle3\">Ethereal Otherworldly beings such as spirits and ghosts.</span></p></li><li><p><span class=\"fontstyle2\">(earth): </span><span class=\"fontstyle3\">Living Tainted beings.</span></p></li><li><p><span class=\"fontstyle2\">(fire): </span><span class=\"fontstyle3\">Undead beings with corporeal form.</span></p></li><li><p><span class=\"fontstyle2\">(water): </span><span class=\"fontstyle3\">Wild animals.</span></p></li><li><p><span class=\"fontstyle2\">(void): </span><span class=\"fontstyle3\">Humans.</span></p></li></ul><h4><span class=\"fontstyle5\">New Opportunities</span></h4><p><span class=\"fontstyle6\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">Instead of protecting a threshold, you may protect the entirety of a sealed area that extends a number of range bands around you no greater than your bonus successes.</span></p><p><span class=\"fontstyle6\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">If any beings of the type you are attempting to seal the threshold against have passed through the threshold within the last twenty-four hours, you become aware of their passage.</span></p>","source":{"book":"core_rulebook","page":213},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.2iB4EK0I42kk83V3","skill":"theology","xp_cost":3},{"name":"Gift of Inner Power","kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">You can infuse other characters with your inner energy. After you perform a check to activate one of your kihō, you can receive fatigue up to your school rank and choose another character at range 0–1. If you do, that character gains the enhancement effect of your kihō in your stead ­you may still resolve the burst effect, if able). This effect persists a number of rounds equal to the amount of fatigue you received this way plus your ranks in Meditation. Only one character can benefit from your kihō at a time.</span></p>","source":{"book":"path_of_waves","page":58},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.xQRMG49wGf3rL3YS","xp_cost":0},{"name":"Sacred Mantras","kind":"title_ability","rank":1,"description":"<p><span class=\"fontstyle0\">You can purchase mantra techniques ­(see page 98).</span></p>","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.zEIXSkkEdDfQUvrd","xp_cost":0}],"peculiarities":[{"name":"Blessed Lineage","kind":"distinction","ring":"void","types":"Interpersonal, Spiritual","description":"<p><span class=\"fontstyle0\"><em>“Perhaps you’d like to match your words with your steel,” the woman growled, her hands resting upon the hilts of her swords. “You will learn a hard lesson: nobody insults Mirumoto Ohatsu with impunity.”</em></span></p><p><span class=\"fontstyle0\"><em>The man she faced smiled in return.</em></span></p><p><span class=\"fontstyle0\"><em>“I certainly did not intend to offend you in any way, Ohatsu-san. Please allow me to introduce myself. I am Miya Matsuo. Perhaps you have heard of my cousin, the Imperial Herald?”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Blessed Lineage distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- Characters with status of 50 or higher understand that they might suffer a loss of prestige if they harm you, and thus do not choose to kill you as their first option, even if you are a political obstacle they would otherwise eliminate without hesitation.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check for which your esteemed lineage is a benefit (such as a Command (void) check to challenge someone’s perception of a situation or a Government (void) check to know the likelihood of a political eventuality), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":103},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.tRfoACKusbLsicmy","xp_cost":3},{"name":"Gaijin Name, Culture, or Appearance","kind":"adversity","ring":"fire","types":"Interpersonal (Culture) or Physical (Appearance), Interpersonal (Name), Mental","description":"<p><em>The Crane courtier bowed deeply, a thin, insincere smile upon his face. “I bring a thousand wishes for a glorious future from the Crane to the great Shinjo Aru…Arutan…”</em></p><p><em>“Altansarnai,” the Unicorn Champion corrected him. The courtier bowed further. “I apologize, Shinjo\u0002sama. A…lovely name, but one that falls oddly upon my tongue.”</em></p><p><em>“It is from the Ujik tongue. It means ‘golden rose.’” Altansarnai gestured for the courtier to join her where she was seated. We are still foreign to them, she thought, and they will never let us forget it.</em></p><p></p><p>The following apply to a character with the Gaijin Name, Culture, or Appearance adversity:</p><ul><li><p>- People of higher and equal status tend to assume that you are uneducated at best and a barbarian at worst, while people of lower status respond to you with fear.</p></li><li><p>- When you make a check to inspire others who do not share your culture or background (such as a Command (fire) check to rally troops or a Commerce (fire) check to create a product that people desire), you must choose and reroll two dice containing (su) or (ex) . After resolving the check, if you failed, you gain 1 Void point.</p></li></ul>","source":{"book":"core_rulebook","page":121},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.FCw1pfvIVYoe5yyk","xp_cost":3},{"name":"Glorious Deeds","kind":"passion","ring":"fire","types":"Martial, Social","description":"<p><span class=\"fontstyle0\"><em>“Even should a samurai evade death on the battlefield and survive to see their great-grandchildren come of age, one day they will pass. Such is the way of mortals. But the stories that people tell of that samurai—those may live forever.” The Ikoma historian gave his sibling a shrewd look.</em></span></p><p><span class=\"fontstyle0\"><em>“But you did not come to listen to the lectures I have for students, I suspect. You want to be the subject of my next lecture. Tell me of your accomplishments, and I will make sure they are recorded in the family histories.”</em></span></p><p><span class=\"fontstyle0\"><em>With that prompting, the eager bushi launched into a story about their efforts in the recent conflict, and they were not silent until late into the night.</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Glorious Deeds passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You find risking your life to be a simple matter, as long as there is a witness to remember your bravery. No threat or challenge deters you if you might be remembered for it, making even the most daunting tasks easy ones for which to prepare.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to improve your reputation or gain fame as a great samurai (such as a Performance (fire) check to impress a court with your new melody, or a Tactics (fire) check to execute a daring raid on the enemy), you remove 3 strife.</span></p></li></ul>","source":{"book":"fields_of_victory","page":83},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.B9fnpC0enRx8DeSO","xp_cost":3},{"name":"Fear of Mediocrity","kind":"anxiety","ring":"fire","types":"Interpersonal, Mental","description":"<p><em>“I have climbed the highest peaks in my quest: the Wrath of the Kami, Tenkenniyoru Yama, the Iron Mountain, the Northern Wall Mountains… Nothing!</em></p><p><em>Each tincture from a flower. Each tea from an herb. Each poultice from bark. Nothing. The answer must be out there.”</em></p><p><em>- letters from Agasha AriNaga regarding an elixir of immortality</em></p><p><em>“Falling up a mountain like AriNaga, to be immortalized as a fool.”</em></p><p><em>- old Agasha saying</em></p><p><strong>Effects:</strong> The following apply to a character with the Fear of Mediocrity anxiety:</p><ul><li><p>-  Your fear of amounting to nothing causes you to seize up when faced with the need to innovate on the fly.</p></li><li><p>-  After performing a check to adapt to an unexpected situation (such as a Survival (fire) check to find shelter when your tent is destroyed or a Culture (fire) check to unexpectedly interact in an appropriate manner with someone of a higher status), you receive 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"writ_of_the_wild","page":106},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.TVReYB8XXXDEQUkr","xp_cost":3},{"name":"Benten’s Blessing","kind":"distinction","ring":"air","types":"Interpersonal, Spiritual","description":"<p><span class=\"fontstyle0\"><em>Daidoji Shingen sauntered down the gangplank from the dock to his waiting vessel, a broad smile spreading across his face. His crew gathered around their returning captain.</em></span></p><p><span class=\"fontstyle0\"><em>“We have safe harbor here, and a fine market in which to sell our cargo. Start offloading.” The crew cheered, and set to work. Shingen’s first mate, Hiramichi Anjiro, remained behind, scratching his head idly.</em></span></p><p><span class=\"fontstyle0\"><em>“I don’t know how you managed that, Captain.” Shingen winked. “Let’s just say that the lady of the palace was kindly disposed toward a wayward sea captain.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Benten’s Blessing distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- After interacting with a character for one or more scenes, you know with certainty whether they are open to your romantic aspirations or if they are categorically uninterested.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check for which the favor of the Fortune Benten is a benefit (such as an Aesthetics (air) check to say something insightful about a piece of art or a Courtesy (air) check to convince someone of your positive qualities), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":102},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.Vi9SQaa3y48ob8Hp","xp_cost":3}],"titles":[{"name":"Astradhari","description":"<p><span class=\"fontstyle0\">Those who wield astras, the celestial implements blessed by the gods, have been given exceptional powers. These heroes and villains are much rarer than they were in ancient times, but they still exist today. The ability to summon such items requires the influence of a god or intense study under a mentor from the Ivory Kingdoms. If a person can find a sage willing to teach them, they may be able to learn how to summon one of these powerful artifacts, but no sage is willing to teach just anyone these sacred and secret methods. A character must complete tests and trials, which differ depending on the sage in question, to prove their worthiness of wielding such intense power.</span></p><p><span class=\"fontstyle2\"><strong>Assigned By:</strong>\u001c</span><span class=\"fontstyle0\">An Ivory Kingdoms High Sage (­such a person may only be chosen by the GM).</span></p><p><span class=\"fontstyle2\"><strong>Status Award:</strong>\u001c+0</span><span class=\"fontstyle0\"> (+25 in the Ivory Kingdoms, to a maximum of 65)</span></p><p><span class=\"fontstyle2\"><strong>Title Ability:</strong> Sacred Mantras</span></p><h2>Curriculum</h2><table><tbody><tr><td><p>Scholar Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Martial Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Command</p></td><td><p>Skill</p></td></tr><tr><td><p>Courtesy</p></td><td><p>Skill</p></td></tr><tr><td><p><a class=\"compendium-link\" data-pack=\"l5r5e.core-techniques-rituals\">(ritual) Rank 1-3 Rituals</a> (prereq)</p></td><td><p>Tech. Grp.</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-mantra.Item.L5RCoreMan000001\" data-pack=\"l5r5e.core-techniques-mantra\" data-type=\"Item\" data-id=\"L5RCoreMan000001\">(mantra) Summon Mantra : [One Implement]</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000011\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000011\">(shuji) Touchstone of Courage</a> (prereq)</p></td><td><p>Technique</p></td></tr></tbody></table>","source":{"book":"path_of_waves","page":187},"uuid":"Compendium.l5r5e-compendia-sortilege.titles-l5r-sortilege.Item.ZxQWnpKClMvn208X","xp_cost":36}],"bonds":[{"name":"Wanderers Fellowship","description":"<p><span class=\"fontstyle0\">With no lord, rōnin have nobody to rely upon and none to protect save themself, making their way through the world like waves rolling across the shore. But even the most independent-minded humans desire a degree of companionship, and there is a certain stability to be found in numbers. As a result, many rōnin form warrior bands, groups that work, fight, suffer, and laugh together. These bonds can become as tight as the tremendously strong bonds of family in Rokugan, or even stronger. In desperate circumstances, this bond can get a rōnin on their feet and back into the fight, helping them to fight on through the pain or face overwhelming odds to save their comrades in arms.</span></p><ul><li><p><span class=\"fontstyle0\">- Other members of your fellowship watch out for your safety (if not always your dignity, especially when it comes to telling embarrassing stories). They help you with modest favors (offering you a cut in on a job they have taken on, giving you an introduction to someone hiring rōnin, buying your sake when your purse is empty and theirs is less empty), and generally expect you to reciprocate such favors.</span></p></li><li><p><span class=\"fontstyle0\">- Those with whom your fellowship has worked before are generally inclined to regard you in the same way they do your fellows—if they are rowdy or well-behaved, they will assume the same of you. Your actions also reflect upon members of your fellowship, and if you step out of line such that it endangers the group’s reputation, they intervene to set you on the right path—or to remove you from the group, if you will not repent.</span></p></li><li><p><span class=\"fontstyle0\">- If your bond rank is 3 or higher, your fellowship’s bonds of loyalty are extremely deep, and other members will accept dangerous jobs with you without question, join your side in battles that do not pay, and perhaps even buy your sake without reminding you about it three times in the next week.</span></p></li></ul><p></p><p><span class=\"fontstyle3\"><strong>Bond Ability:</strong> Sworn to Duty and to Death</span></p>","source":{"book":"path_of_waves","page":191},"uuid":"Compendium.l5r5e-compendia-sortilege.bonds-l5r-sortilege.Item.ItUUhYTr7vst11ZH","xp_cost":3}],"gear":[{"name":"Talwar","quantity":1,"description":"<p><span class=\"fontstyle0\">The Ivory Kingdoms sidearm is the </span><span class=\"fontstyle2\">talwar</span><span class=\"fontstyle0\">, or “single-edged sword.” A curved saber with one sharp edge and a cross-guarded hilt with a knuckle-bow, it is designed to be wielded in a specialized one-handed grip. The sword’s hilt is bulb shaped, requiring that the sword be held differently than those forged by Rokugani. This and the blade’s unusual balance means that talwar fighting requires special training; attempting</span> <span class=\"fontstyle0\">to use the sword as one might a Rokugani blade can break the talwar or injure one’s wrist. However, when a talwar is wielded correctly, the wider cutting tip at the end of its blade affords it more cutting power, making this sidearm an especially deadly weapon.</span></p>","source":{"book":"path_of_waves","page":113},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.tSwkJCF7OSXTVnvY","damage":4,"deadliness":6,"range":"1","grip_2":"N/A","skill":"melee","category":"Swords","rarity":"8","zeni":"35 koku","properties":[{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Daikyū","quantity":1,"description":"<p><span class=\"fontstyle0\">Daikyū are large composite bows designed to be fired from horseback. Conventionally around six feet long, these elegant weapons are constructed by gluing thin layers of wood, horn, leather, and sinew together. Daikyū differ from other bows in that they have an asymmetric shape. Their grip is about two-thirds of the way from the top, making the top curve longer than the bottom. This allows the bows to be fired easily from horseback in either direction. Each daikyū is made for a custom fit for a specific user.</span></p>","source":{"book":"core_rulebook","page":236},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.sjVz7tI11BkNAA7t","damage":6,"deadliness":4,"range":"3-5","grip_1":"N/A","skill":"ranged","category":"Bows","rarity":"6","zeni":"6 koku","properties":[{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Gunbai","quantity":1,"description":"<p><span class=\"fontstyle0\">The gunbai, a leader or commander’s war fan, is a staple of samurai officers for communicating orders to their troops at a distance. Each gunbai is unique, as are the gestures the officers use to communicate orders to their troops. With a flick of the wrist, an officer may order their troops to fall back or to charge into the fray. Often gilded with metal, a gunbai is used to convey urgent tactical shifts and defensive moves.</span></p><p><span class=\"fontstyle0\">A gunbai can be wielded as a one-handed Martial Arts [Melee] weapon with the following profile: Range 1, Damage 2, Deadliness 2.</span></p><p><span class=\"fontstyle0\">During a skirmish, a character with a gunbai readied can perform shūji targeting characters who can see them at range 0–6 (as opposed to the usual auditory range restriction of range 0–4).</span></p><p><span class=\"fontstyle0\">During a mass battle, for each of an army’s leaders equipped with a gunbai, the army increases its discipline by 2.</span></p>","source":{"book":"fields_of_victory","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.7OWReYbIMfTvNrqv","damage":2,"deadliness":2,"range":"1","grip_2":"N/A","skill":"melee","category":"Hand Weapons","rarity":"4","zeni":"3 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Sanctified Robes","quantity":1,"description":"<p><span class=\"fontstyle0\">The vestments of shugenja, shrine keepers, and other religious figures are blessed by kami and thus grant mystical protection. Traditionally, such robes consist of a white garment called </span><span class=\"fontstyle2\">jōe </span><span class=\"fontstyle0\">(literally, “pure cloth”) and a peaked hat, but they can be simpler, such as a white haori top and red hakama bottoms, or even an elaborate kimono.</span></p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.Cq1koK56k9dvLfMh","armor":{"physical":1,"supernatural":3},"rarity":"7","zeni":"4 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p><span class=\"fontstyle0\">Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak</span>.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Map (Ivory Kingdoms)","quantity":1,"custom":true,"description":"<p><span class=\"fontstyle0\">Showing the route from the Ivory Kingdoms to the Sand Road</span>.</p>","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Signet Ring (Royal Family)","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Uma-Jirushi","quantity":1,"description":"<p>Resembling a soldier’s sashimono banner, the massive, heraldic uma-jirushi banner sets a daimyō or general apart as they ride into battle. While some uma-jirushi may simply be larger, more ornate sashimono, some daimyō contract artisans to create elaborate, three-dimensional shapes or even entreat shugenja to add elemental flourishes (such as a perpetual, slow-burning flame or a constant gust of wind) to make their banner stand out.</p><p data-start=\"440\" data-end=\"748\" data-is-last-node=\"\" data-is-only-node=\"\">When making a Command check, a leader in a mass battle who displays a personal uma-jirushi adds one kept  set to . Should the bearer of an uma-jirushi be killed via the Cut Off the Head or Challenge action, their army receives 4 additional panic. (Cost: 3 koku. Rarity: 7. Qualities: Resplendent, Wargear.)</p>","source":{"book":"fields_of_victory","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.uaCKNEXDlq1OI3wO","rarity":"7","zeni":"3 koku","properties":[{"id":"L5RCorePro000010","name":"Resplendent"},{"id":"L5RCorePro000011","name":"Wargear"}]}]},{"xp":57,"label":"Astradhari, Rank 2","rank":2,"school":"Ivory Kingdoms Sage Tradition","foundry_id":"ekaguEV9oUfUZ9E5","rings":{"air":2,"earth":2,"fire":2,"water":2,"void":2},"skills":{"artisan":{"aesthetics":0,"composition":0,"design":0,"smithing":0},"martial":{"fitness":1,"melee":1,"ranged":4,"unarmed":2,"meditation":1,"tactics":0},"scholar":{"culture":1,"government":0,"medicine":0,"sentiment":0,"theology":1},"social":{"command":3,"courtesy":1,"games":0,"performance":0},"trade":{"commerce":0,"labor":0,"seafaring":1,"skulduggery":0,"survival":0}},"social":{"honor":50,"glory":33,"status":0,"ninjo":"Regain his home; he seeks to reconquer his homeland.","giri":"Aarav's family was betrayed, his brothers executed; he fled east.","bushido_tenets":{"paramount":"","less_significant":""}},"derived":{"endurance":8,"composure":8,"focus":4,"vigilance":2,"void_points":2},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Fitness +1 (0 -> 1)","type":"skill","skill":"fitness","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Martial Arts [Unarmed] +1 (1 -> 2)","type":"skill","skill":"unarmed","ring":"void","at_rank":1,"xp":4,"in_curriculum":true}],"techniques":[{"name":"Earth Needs No Eyes","kind":"kiho","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The monk who waits and listens sees much, even without eyes. Sending out waves of their own energy and letting the ki of the life around them flow back into their body through the ground, the monk feels the reverberations of everything moving nearby, from the thunderous breaths of a warrior in battle to the footsteps of the tiniest ants.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may activate this kihō. When you do so, you may make a </span><span class=\"fontstyle2\">TN 1 Meditation (earth) check </span><span class=\"fontstyle3\">to gain an awareness of your surroundings.</span></p><p><span class=\"fontstyle2\"><strong>Enhancement Effect:</strong> </span><span class=\"fontstyle3\">If you succeed, this kihō activates. While this kihō is active, you can use vibrations through the earth to “see” a number of range bands in all directions equal to your Earth Ring. While this kihō is active, increase your vigilance by your Earth Ring.</span></p><p><span class=\"fontstyle2\"><strong>Burst Effect:</strong> </span><span class=\"fontstyle3\">If you succeed with three or more bonus successes, you instantly become aware of all living creatures and objects touching the ground within a number of range bands equal to your Earth Ring plus your bonus successes.</span></p>","source":{"book":"core_rulebook","page":182},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kiho-l5r-sortilege.Item.qFpqm3GpkCEAu6z2","skill":"meditation","xp_cost":3},{"name":"Cleansing Spirit","kind":"kiho","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The monk centers their ki, then reaches out and touches another character, counterbalancing their turbulent energies with the stillness of the monk’s own soul. This restores the character’s spirit, driving out poison, disease, and even the grip of evil spirits, provided they have not yet taken root in the character’s soul.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, may make a </span><span class=\"fontstyle2\">TN 1 Theology (earth) check </span><span class=\"fontstyle3\">to bolster your spiritual resilience. When you perform this action, you may choose one other character at range 0–1 as the target for the burst effect.</span></p><p><span class=\"fontstyle2\"><strong>Enhancement Effect:</strong> </span><span class=\"fontstyle3\">If you succeed, this kihō activates. While this kihō is active, reduce the TN of all your checks to resist poison, disease, mahō, the Defiled terrain quality, and the effects of Otherworldly and Tainted beings by your Earth Ring.</span></p><p><span class=\"fontstyle2\"><strong>Burst Effect:</strong> </span><span class=\"fontstyle3\">If you have two or more bonus successes, remove one of the following conditions from your target: Afflicted, Bleeding, Dazed, Disoriented, Dying, Fatigued, or Intoxicated.</span></p>","source":{"book":"core_rulebook","page":182},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kiho-l5r-sortilege.Item.5jLb6bvrYkwlkSc8","skill":"theology","xp_cost":3},{"name":"Threshold Barrier","kind":"ritual","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The ritualist wards an entryway against beings of a certain sort, causing them to fail to observe the entryway or making them mentally repulsed by their efforts to enter it.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a downtime activity, you may make a </span><span class=\"fontstyle2\">TN 2 Theology check </span><span class=\"fontstyle3\">using (air), (earth), (fire), (water), or (void) targeting a threshold, gate, or other entryway at range 0–1.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, the threshold is barred against a particular type of entity, based on the ring you chose, for one hour, plus additional hours equal to your bonus successes. When an entity of this type attempts to enter, it must resist with a </span><span class=\"fontstyle2\">TN 3 Meditation (void) check </span><span class=\"fontstyle3\">or be repelled by the spiritual barrier. Whether it succeeds or fails, you immediately become aware of its attempted entry. The particular type of being is based on the ring you chose, as follows:</span></p><ul><li><p><span class=\"fontstyle2\">(air): </span><span class=\"fontstyle3\">Ethereal Otherworldly beings such as spirits and ghosts.</span></p></li><li><p><span class=\"fontstyle2\">(earth): </span><span class=\"fontstyle3\">Living Tainted beings.</span></p></li><li><p><span class=\"fontstyle2\">(fire): </span><span class=\"fontstyle3\">Undead beings with corporeal form.</span></p></li><li><p><span class=\"fontstyle2\">(water): </span><span class=\"fontstyle3\">Wild animals.</span></p></li><li><p><span class=\"fontstyle2\">(void): </span><span class=\"fontstyle3\">Humans.</span></p></li></ul><h4><span class=\"fontstyle5\">New Opportunities</span></h4><p><span class=\"fontstyle6\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">Instead of protecting a threshold, you may protect the entirety of a sealed area that extends a number of range bands around you no greater than your bonus successes.</span></p><p><span class=\"fontstyle6\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">If any beings of the type you are attempting to seal the threshold against have passed through the threshold within the last twenty-four hours, you become aware of their passage.</span></p>","source":{"book":"core_rulebook","page":213},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.2iB4EK0I42kk83V3","skill":"theology","xp_cost":3},{"name":"Gift of Inner Power","kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">You can infuse other characters with your inner energy. After you perform a check to activate one of your kihō, you can receive fatigue up to your school rank and choose another character at range 0–1. If you do, that character gains the enhancement effect of your kihō in your stead ­you may still resolve the burst effect, if able). This effect persists a number of rounds equal to the amount of fatigue you received this way plus your ranks in Meditation. Only one character can benefit from your kihō at a time.</span></p>","source":{"book":"path_of_waves","page":58},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.xQRMG49wGf3rL3YS","xp_cost":0},{"name":"Sacred Mantras","kind":"title_ability","rank":1,"description":"<p><span class=\"fontstyle0\">You can purchase mantra techniques ­(see page 98).</span></p>","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.zEIXSkkEdDfQUvrd","xp_cost":0},{"name":"Countering Mantra","kind":"mantra","rank":4,"description":"<p><span class=\"fontstyle0\"><strong>Activation:</strong> </span><span class=\"fontstyle2\">When a character you can perceive makes a check to use a celestial implement, if you have a readied celestial implement of your own, you may immediately make a </span><span class=\"fontstyle0\">TN 5 Theology check </span><span class=\"fontstyle2\">targeting that character to attempt to counter their implement’s effects. If your celestial implement’s element matches the </span><span class=\"fontstyle0\">counter element </span><span class=\"fontstyle2\">of the target’s implement, the TN is 2 instead.</span></p><p><span class=\"fontstyle0\"><strong>Effects:</strong> </span><span class=\"fontstyle2\">If you succeed, your target’s implement is </span><span class=\"fontstyle3\">dispelled</span><span class=\"fontstyle2\">. Your target counts as having failed the check to use it, with a shortfall equal to your ranks in Theology, and they do not apply any of its boons to the check.</span></p>","source":{"book":"path_of_waves","page":99},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-mantra-l5r-sortilege.Item.wRG952uD4IVgzJLm","skill":"theology","xp_cost":3},{"name":"Ki Protection","kind":"kiho","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The monk touches the injured individual, feeling the flow of their ki and using their own to gently correct its flow. While the monk sustains this kihō, their touch continues to heal, though repeating the effort numerous times is quite draining.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Movement and Support action, you may make a </span><span class=\"fontstyle2\">TN 1 Meditation (water) check. </span><span class=\"fontstyle3\">You may choose one character at range 0–1 as the target for the burst effect.</span></p><p><span class=\"fontstyle2\"><strong>Enhancement Effect:</strong> </span><span class=\"fontstyle3\">If you succeed, this kihō activates. While this kihō is active, when you perform the Calming Breath action, you may remove 2 fatigue instead of 1. While this kihō is active, after you perform an action, you may spend 1 Void point to remove fatigue equal to your ranks in Medicine from one other character at range 0–1.</span></p><p><span class=\"fontstyle2\"><strong>Burst Effect:</strong> </span><span class=\"fontstyle3\">If you have 2 or more bonus successes, your target removes fatigue equal to your ranks in Medicine plus your bonus successes. Each target cannot be affected by this effect again until the end of the scene.</span></p>","source":{"book":"core_rulebook","page":186},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kiho-l5r-sortilege.Item.x6T3VxPFnPdxf2xk","skill":"meditation","xp_cost":3},{"name":"The Great Silence","kind":"kiho","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The monk swirls their hands in a spiral, pulling noise inward and stealing even the reverberations that sounds make through the air. Lies die on the lips unspoken, and prayers never reach the spirits for whom they were intended. Skilled practitioners often maintain this technique, twisting the wind around them to steal away pernicious words and wicked prayers alike.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Scheme and Support action, you may activate this kihō, you may make a </span><span class=\"fontstyle2\">TN 1 Theology (air) check </span><span class=\"fontstyle3\">to create an area of silence around you.</span></p><p><span class=\"fontstyle2\"><strong>Enhancement Effect:</strong> </span><span class=\"fontstyle3\">If you succeed, this kihō activates. While this kihō is active, increase the TN of Scheme action checks targeting you by one plus your ranks in Command.</span></p><p><span class=\"fontstyle2\"><strong>Burst Effect:</strong> </span><span class=\"fontstyle3\">If you have two or more bonus successes, characters at range 0–3 suffer the Silenced condition (see page 273) and cannot hear. This effect persists until the beginning of your next turn.</span></p>","source":{"book":"core_rulebook","page":184},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kiho-l5r-sortilege.Item.23p9KHaq2jGc7DAu","skill":"theology","xp_cost":3},{"name":"Bellow of Resolve","kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>A well-timed word of encouragement or shout of warning can get a fighter back on their feet at a crucial moment, which can mean the difference between life and death on the battlefield.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">Once per scene as a Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Command (earth) check </span><span class=\"fontstyle3\">targeting one Compromised or Incapacitated character.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed and your target is Compromised, they remove strife until their strife is equal to their composure minus 1.</span></p><p><span class=\"fontstyle3\">If you succeed and your target is Incapacitated, they remove fatigue until their fatigue is equal to their endurance minus 1.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(earth)(op)(op): </span><span class=\"fontstyle3\">You may use this technique one additional time this scene.</span></p><p><span class=\"fontstyle2\">(earth)(op)(op)(op): </span><span class=\"fontstyle3\">This technique instead targets any number of Compromised and Incapacitated characters of your choice in the scene.</span></p>","source":{"book":"path_of_waves","page":92},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.Kf6YB5RNjbesovz6","skill":"command","xp_cost":3},{"name":"Landslide Strike","kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Lashing out at the foe’s legs, the warrior forces their enemy to either abandon their stance or be knocked from their feet. This tactic is especially effective on uneven ground, as the enemy must watch their footing or risk even further injury.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack and Scheme action, you may make a </span><span class=\"fontstyle2\">Martial Arts [Melee] ((earth) </span><span class=\"fontstyle3\">or </span><span class=\"fontstyle2\">(water)) check </span><span class=\"fontstyle3\">targeting one character in your weapon’s range. The TN is equal to the target’s vigilance. If your target is in Dangerous, Entangling, or Obscuring terrain, the TN is 1 instead.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target must choose one of the following:</span></p><ul><li><p><span class=\"fontstyle3\">- Receive fatigue equal to your ranks in Fitness and the Prone condition.</span></p></li><li><p><span class=\"fontstyle3\">- Switch to a different stance of their choice and suffer the Immobilized condition.</span></p></li></ul><h4><span class=\"fontstyle5\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(op)(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">If your weapon has the Cumbersome quality, choose one additional target with vigilance lower than or equal to your original target’s vigilance per (op)(op) spent this way.</span></p>","source":{"book":"path_of_waves","page":89},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.zK3HcHrVGitDdyHt","skill":"melee","xp_cost":3}],"peculiarities":[{"name":"Blessed Lineage","kind":"distinction","ring":"void","types":"Interpersonal, Spiritual","description":"<p><span class=\"fontstyle0\"><em>“Perhaps you’d like to match your words with your steel,” the woman growled, her hands resting upon the hilts of her swords. “You will learn a hard lesson: nobody insults Mirumoto Ohatsu with impunity.”</em></span></p><p><span class=\"fontstyle0\"><em>The man she faced smiled in return.</em></span></p><p><span class=\"fontstyle0\"><em>“I certainly did not intend to offend you in any way, Ohatsu-san. Please allow me to introduce myself. I am Miya Matsuo. Perhaps you have heard of my cousin, the Imperial Herald?”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Blessed Lineage distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- Characters with status of 50 or higher understand that they might suffer a loss of prestige if they harm you, and thus do not choose to kill you as their first option, even if you are a political obstacle they would otherwise eliminate without hesitation.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check for which your esteemed lineage is a benefit (such as a Command (void) check to challenge someone’s perception of a situation or a Government (void) check to know the likelihood of a political eventuality), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":103},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.tRfoACKusbLsicmy","xp_cost":3},{"name":"Gaijin Name, Culture, or Appearance","kind":"adversity","ring":"fire","types":"Interpersonal (Culture) or Physical (Appearance), Interpersonal (Name), Mental","description":"<p><em>The Crane courtier bowed deeply, a thin, insincere smile upon his face. “I bring a thousand wishes for a glorious future from the Crane to the great Shinjo Aru…Arutan…”</em></p><p><em>“Altansarnai,” the Unicorn Champion corrected him. The courtier bowed further. “I apologize, Shinjo\u0002sama. A…lovely name, but one that falls oddly upon my tongue.”</em></p><p><em>“It is from the Ujik tongue. It means ‘golden rose.’” Altansarnai gestured for the courtier to join her where she was seated. We are still foreign to them, she thought, and they will never let us forget it.</em></p><p></p><p>The following apply to a character with the Gaijin Name, Culture, or Appearance adversity:</p><ul><li><p>- People of higher and equal status tend to assume that you are uneducated at best and a barbarian at worst, while people of lower status respond to you with fear.</p></li><li><p>- When you make a check to inspire others who do not share your culture or background (such as a Command (fire) check to rally troops or a Commerce (fire) check to create a product that people desire), you must choose and reroll two dice containing (su) or (ex) . After resolving the check, if you failed, you gain 1 Void point.</p></li></ul>","source":{"book":"core_rulebook","page":121},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.FCw1pfvIVYoe5yyk","xp_cost":3},{"name":"Glorious Deeds","kind":"passion","ring":"fire","types":"Martial, Social","description":"<p><span class=\"fontstyle0\"><em>“Even should a samurai evade death on the battlefield and survive to see their great-grandchildren come of age, one day they will pass. Such is the way of mortals. But the stories that people tell of that samurai—those may live forever.” The Ikoma historian gave his sibling a shrewd look.</em></span></p><p><span class=\"fontstyle0\"><em>“But you did not come to listen to the lectures I have for students, I suspect. You want to be the subject of my next lecture. Tell me of your accomplishments, and I will make sure they are recorded in the family histories.”</em></span></p><p><span class=\"fontstyle0\"><em>With that prompting, the eager bushi launched into a story about their efforts in the recent conflict, and they were not silent until late into the night.</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Glorious Deeds passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You find risking your life to be a simple matter, as long as there is a witness to remember your bravery. No threat or challenge deters you if you might be remembered for it, making even the most daunting tasks easy ones for which to prepare.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to improve your reputation or gain fame as a great samurai (such as a Performance (fire) check to impress a court with your new melody, or a Tactics (fire) check to execute a daring raid on the enemy), you remove 3 strife.</span></p></li></ul>","source":{"book":"fields_of_victory","page":83},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.B9fnpC0enRx8DeSO","xp_cost":3},{"name":"Fear of Mediocrity","kind":"anxiety","ring":"fire","types":"Interpersonal, Mental","description":"<p><em>“I have climbed the highest peaks in my quest: the Wrath of the Kami, Tenkenniyoru Yama, the Iron Mountain, the Northern Wall Mountains… Nothing!</em></p><p><em>Each tincture from a flower. Each tea from an herb. Each poultice from bark. Nothing. The answer must be out there.”</em></p><p><em>- letters from Agasha AriNaga regarding an elixir of immortality</em></p><p><em>“Falling up a mountain like AriNaga, to be immortalized as a fool.”</em></p><p><em>- old Agasha saying</em></p><p><strong>Effects:</strong> The following apply to a character with the Fear of Mediocrity anxiety:</p><ul><li><p>-  Your fear of amounting to nothing causes you to seize up when faced with the need to innovate on the fly.</p></li><li><p>-  After performing a check to adapt to an unexpected situation (such as a Survival (fire) check to find shelter when your tent is destroyed or a Culture (fire) check to unexpectedly interact in an appropriate manner with someone of a higher status), you receive 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"writ_of_the_wild","page":106},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.TVReYB8XXXDEQUkr","xp_cost":3},{"name":"Benten’s Blessing","kind":"distinction","ring":"air","types":"Interpersonal, Spiritual","description":"<p><span class=\"fontstyle0\"><em>Daidoji Shingen sauntered down the gangplank from the dock to his waiting vessel, a broad smile spreading across his face. His crew gathered around their returning captain.</em></span></p><p><span class=\"fontstyle0\"><em>“We have safe harbor here, and a fine market in which to sell our cargo. Start offloading.” The crew cheered, and set to work. Shingen’s first mate, Hiramichi Anjiro, remained behind, scratching his head idly.</em></span></p><p><span class=\"fontstyle0\"><em>“I don’t know how you managed that, Captain.” Shingen winked. “Let’s just say that the lady of the palace was kindly disposed toward a wayward sea captain.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Benten’s Blessing distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- After interacting with a character for one or more scenes, you know with certainty whether they are open to your romantic aspirations or if they are categorically uninterested.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check for which the favor of the Fortune Benten is a benefit (such as an Aesthetics (air) check to say something insightful about a piece of art or a Courtesy (air) check to convince someone of your positive qualities), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":102},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.Vi9SQaa3y48ob8Hp","xp_cost":3}],"titles":[{"name":"Astradhari","description":"<p><span class=\"fontstyle0\">Those who wield astras, the celestial implements blessed by the gods, have been given exceptional powers. These heroes and villains are much rarer than they were in ancient times, but they still exist today. The ability to summon such items requires the influence of a god or intense study under a mentor from the Ivory Kingdoms. If a person can find a sage willing to teach them, they may be able to learn how to summon one of these powerful artifacts, but no sage is willing to teach just anyone these sacred and secret methods. A character must complete tests and trials, which differ depending on the sage in question, to prove their worthiness of wielding such intense power.</span></p><p><span class=\"fontstyle2\"><strong>Assigned By:</strong>\u001c</span><span class=\"fontstyle0\">An Ivory Kingdoms High Sage (­such a person may only be chosen by the GM).</span></p><p><span class=\"fontstyle2\"><strong>Status Award:</strong>\u001c+0</span><span class=\"fontstyle0\"> (+25 in the Ivory Kingdoms, to a maximum of 65)</span></p><p><span class=\"fontstyle2\"><strong>Title Ability:</strong> Sacred Mantras</span></p><h2>Curriculum</h2><table><tbody><tr><td><p>Scholar Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Martial Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Command</p></td><td><p>Skill</p></td></tr><tr><td><p>Courtesy</p></td><td><p>Skill</p></td></tr><tr><td><p><a class=\"compendium-link\" data-pack=\"l5r5e.core-techniques-rituals\">(ritual) Rank 1-3 Rituals</a> (prereq)</p></td><td><p>Tech. Grp.</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-mantra.Item.L5RCoreMan000001\" data-pack=\"l5r5e.core-techniques-mantra\" data-type=\"Item\" data-id=\"L5RCoreMan000001\">(mantra) Summon Mantra : [One Implement]</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000011\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000011\">(shuji) Touchstone of Courage</a> (prereq)</p></td><td><p>Technique</p></td></tr></tbody></table>","source":{"book":"path_of_waves","page":187},"uuid":"Compendium.l5r5e-compendia-sortilege.titles-l5r-sortilege.Item.ZxQWnpKClMvn208X","xp_cost":36}],"bonds":[{"name":"Wanderers Fellowship","description":"<p><span class=\"fontstyle0\">With no lord, rōnin have nobody to rely upon and none to protect save themself, making their way through the world like waves rolling across the shore. But even the most independent-minded humans desire a degree of companionship, and there is a certain stability to be found in numbers. As a result, many rōnin form warrior bands, groups that work, fight, suffer, and laugh together. These bonds can become as tight as the tremendously strong bonds of family in Rokugan, or even stronger. In desperate circumstances, this bond can get a rōnin on their feet and back into the fight, helping them to fight on through the pain or face overwhelming odds to save their comrades in arms.</span></p><ul><li><p><span class=\"fontstyle0\">- Other members of your fellowship watch out for your safety (if not always your dignity, especially when it comes to telling embarrassing stories). They help you with modest favors (offering you a cut in on a job they have taken on, giving you an introduction to someone hiring rōnin, buying your sake when your purse is empty and theirs is less empty), and generally expect you to reciprocate such favors.</span></p></li><li><p><span class=\"fontstyle0\">- Those with whom your fellowship has worked before are generally inclined to regard you in the same way they do your fellows—if they are rowdy or well-behaved, they will assume the same of you. Your actions also reflect upon members of your fellowship, and if you step out of line such that it endangers the group’s reputation, they intervene to set you on the right path—or to remove you from the group, if you will not repent.</span></p></li><li><p><span class=\"fontstyle0\">- If your bond rank is 3 or higher, your fellowship’s bonds of loyalty are extremely deep, and other members will accept dangerous jobs with you without question, join your side in battles that do not pay, and perhaps even buy your sake without reminding you about it three times in the next week.</span></p></li></ul><p></p><p><span class=\"fontstyle3\"><strong>Bond Ability:</strong> Sworn to Duty and to Death</span></p>","source":{"book":"path_of_waves","page":191},"uuid":"Compendium.l5r5e-compendia-sortilege.bonds-l5r-sortilege.Item.ItUUhYTr7vst11ZH","xp_cost":3}],"gear":[{"name":"Talwar","quantity":1,"description":"<p><span class=\"fontstyle0\">The Ivory Kingdoms sidearm is the </span><span class=\"fontstyle2\">talwar</span><span class=\"fontstyle0\">, or “single-edged sword.” A curved saber with one sharp edge and a cross-guarded hilt with a knuckle-bow, it is designed to be wielded in a specialized one-handed grip. The sword’s hilt is bulb shaped, requiring that the sword be held differently than those forged by Rokugani. This and the blade’s unusual balance means that talwar fighting requires special training; attempting</span> <span class=\"fontstyle0\">to use the sword as one might a Rokugani blade can break the talwar or injure one’s wrist. However, when a talwar is wielded correctly, the wider cutting tip at the end of its blade affords it more cutting power, making this sidearm an especially deadly weapon.</span></p>","source":{"book":"path_of_waves","page":113},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.tSwkJCF7OSXTVnvY","damage":4,"deadliness":6,"range":"1","grip_2":"N/A","skill":"melee","category":"Swords","rarity":"8","zeni":"35 koku","properties":[{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Daikyū","quantity":1,"description":"<p><span class=\"fontstyle0\">Daikyū are large composite bows designed to be fired from horseback. Conventionally around six feet long, these elegant weapons are constructed by gluing thin layers of wood, horn, leather, and sinew together. Daikyū differ from other bows in that they have an asymmetric shape. Their grip is about two-thirds of the way from the top, making the top curve longer than the bottom. This allows the bows to be fired easily from horseback in either direction. Each daikyū is made for a custom fit for a specific user.</span></p>","source":{"book":"core_rulebook","page":236},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.sjVz7tI11BkNAA7t","damage":6,"deadliness":4,"range":"3-5","grip_1":"N/A","skill":"ranged","category":"Bows","rarity":"6","zeni":"6 koku","properties":[{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Gunbai","quantity":1,"description":"<p><span class=\"fontstyle0\">The gunbai, a leader or commander’s war fan, is a staple of samurai officers for communicating orders to their troops at a distance. Each gunbai is unique, as are the gestures the officers use to communicate orders to their troops. With a flick of the wrist, an officer may order their troops to fall back or to charge into the fray. Often gilded with metal, a gunbai is used to convey urgent tactical shifts and defensive moves.</span></p><p><span class=\"fontstyle0\">A gunbai can be wielded as a one-handed Martial Arts [Melee] weapon with the following profile: Range 1, Damage 2, Deadliness 2.</span></p><p><span class=\"fontstyle0\">During a skirmish, a character with a gunbai readied can perform shūji targeting characters who can see them at range 0–6 (as opposed to the usual auditory range restriction of range 0–4).</span></p><p><span class=\"fontstyle0\">During a mass battle, for each of an army’s leaders equipped with a gunbai, the army increases its discipline by 2.</span></p>","source":{"book":"fields_of_victory","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.7OWReYbIMfTvNrqv","damage":2,"deadliness":2,"range":"1","grip_2":"N/A","skill":"melee","category":"Hand Weapons","rarity":"4","zeni":"3 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Sanctified Robes","quantity":1,"description":"<p><span class=\"fontstyle0\">The vestments of shugenja, shrine keepers, and other religious figures are blessed by kami and thus grant mystical protection. Traditionally, such robes consist of a white garment called </span><span class=\"fontstyle2\">jōe </span><span class=\"fontstyle0\">(literally, “pure cloth”) and a peaked hat, but they can be simpler, such as a white haori top and red hakama bottoms, or even an elaborate kimono.</span></p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.Cq1koK56k9dvLfMh","armor":{"physical":1,"supernatural":3},"rarity":"7","zeni":"4 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p><span class=\"fontstyle0\">Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak</span>.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Map (Ivory Kingdoms)","quantity":1,"custom":true,"description":"<p><span class=\"fontstyle0\">Showing the route from the Ivory Kingdoms to the Sand Road</span>.</p>","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Signet Ring (Royal Family)","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Uma-Jirushi","quantity":1,"description":"<p>Resembling a soldier’s sashimono banner, the massive, heraldic uma-jirushi banner sets a daimyō or general apart as they ride into battle. While some uma-jirushi may simply be larger, more ornate sashimono, some daimyō contract artisans to create elaborate, three-dimensional shapes or even entreat shugenja to add elemental flourishes (such as a perpetual, slow-burning flame or a constant gust of wind) to make their banner stand out.</p><p data-start=\"440\" data-end=\"748\" data-is-last-node=\"\" data-is-only-node=\"\">When making a Command check, a leader in a mass battle who displays a personal uma-jirushi adds one kept  set to . Should the bearer of an uma-jirushi be killed via the Cut Off the Head or Challenge action, their army receives 4 additional panic. (Cost: 3 koku. Rarity: 7. Qualities: Resplendent, Wargear.)</p>","source":{"book":"fields_of_victory","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.uaCKNEXDlq1OI3wO","rarity":"7","zeni":"3 koku","properties":[{"id":"L5RCorePro000010","name":"Resplendent"},{"id":"L5RCorePro000011","name":"Wargear"}]}]}]};
